experimentSourceSnapshots.examples/audit-repair-comparison/results:
import {
	assess as sharedAssess,
	summarize as sharedSummary,
	type Cell as SharedCell,
} from "../operative-sources-comparison/results.ts";
import type { AnswerContext } from "../multi-source-comparison/world.ts";
import { arms, type Arm } from "./protocol.ts";
import type { SourceQuestion } from "./fixtures.ts";
export function assess(
	q: SourceQuestion,
	context: AnswerContext,
	_arm: Arm,
	raw: string,
) {
	const score = sharedAssess(q, context, "baseline", raw);
	return score;
}
export interface Cell extends Omit<SharedCell, "arm"> {
	arm: Arm;
	raw?: string;
	review?: Omit<
		Awaited<ReturnType<typeof import("./review.ts").review>>,
		"raw" | "inputTokens" | "outputTokens" | "latencyMs"
	>;
}
export function summarize(
	cells: readonly Cell[],
	questions: readonly SourceQuestion[],
) {
	function aggregate(qs: readonly SourceQuestion[]) {
		const byArm = Object.fromEntries(
			arms.map((arm) => [
				arm,
				sharedSummary(
					cells
						.filter((c) => c.arm === arm)
						.map((c) => ({ ...c, arm: "baseline" })),
					qs,
				).all.byArm.baseline!,
			]),
		);
		function pair(reference: Arm, candidate: Arm) {
			return sharedSummary(
				cells
					.filter((c) => c.arm === reference || c.arm === candidate)
					.map((c) => ({
						...c,
						arm: c.arm === reference ? "baseline" : "operative",
					})),
				qs,
			).all.pairs;
		}
		return {
			byArm,
			pairs: {
				versusBaseline: pair("baseline", "audit"),
				versusControl: pair("control", "audit"),
				controlVersusBaseline: pair("baseline", "control"),
			},
		};
	}
	return {
		all: aggregate(questions),
		regression: aggregate(questions.filter((q) => q.suite === "regression")),
		unseen: aggregate(questions.filter((q) => q.suite === "unseen")),
		byPacket: Object.fromEntries(
			[...new Set(questions.map((q) => q.packet))].map((id) => [
				id,
				aggregate(questions.filter((q) => q.packet === id)),
			]),
		),
	};
}

import {
	auditGrounding,
	parseGroundedAnswer,
} from "../multi-source-comparison/grounding.ts";
import type { AnswerContext } from "../multi-source-comparison/world.ts";
import type { Question } from "../multi-source-comparison/fixtures.ts";
import { presentation, schemaFor, type Arm } from "./protocol.ts";
export function inspect(raw: string, context: AnswerContext) {
	try {
		const audit = auditGrounding(parseGroundedAnswer(raw), context);
		return { passed: audit.passed, audit, parseError: null };
	} catch (e) {
		return {
			passed: false,
			audit: null,
			parseError: e instanceof Error ? e.message : String(e),
		};
	}
}
export type Inspection = ReturnType<typeof inspect>;
export interface Response {
	raw: string;
	inputTokens: number;
	outputTokens: number;
	latencyMs: number;
}
export function reviewPrompt(
	question: Question,
	context: AnswerContext,
	raw: string,
	arm: "control" | "audit",
) {
	return JSON.stringify({
		task: "Review the previous answer against the original evidence and return a complete answer.",
		originalInput: JSON.parse(presentation(question, context)),
		previousAnswer: raw,
		...(arm === "audit" ? { structuralAudit: inspect(raw, context) } : {}),
	});
}
export async function review(
	question: Question,
	context: AnswerContext,
	initial: Response,
	arm: Arm,
	run: (prompt: string, schema: unknown) => Promise<Response>,
) {
	const initialAudit = inspect(initial.raw, context);
	if (arm === "baseline" || initialAudit.passed)
		return {
			...initial,
			initialAudit,
			finalAudit: initialAudit,
			repairAttempted: false,
			accepted: initialAudit.passed,
			outcome:
				arm === "baseline" ? ("baseline" as const) : ("unchanged" as const),
		};
	const revised = await run(
		reviewPrompt(question, context, initial.raw, arm),
		schemaFor(context),
	);
	const finalAudit = inspect(revised.raw, context);
	return {
		...revised,
		inputTokens: initial.inputTokens + revised.inputTokens,
		outputTokens: initial.outputTokens + revised.outputTokens,
		latencyMs: initial.latencyMs + revised.latencyMs,
		initialAudit,
		finalAudit,
		repairAttempted: true,
		accepted: finalAudit.passed,
		outcome: finalAudit.passed ? ("repaired" as const) : ("rejected" as const),
	};
}

